            regression_wave_regression_wave_cutoff, bool
        ) or not isinstance(
            regression_wave_regression_wave_cutoff, int
        ):
            raise TypeError(
                f"{name} must be an int, got "
                f"{type(regression_wave_regression_wave_cutoff).__name__}"
            )
        if regression_wave_regression_wave_cutoff < 0:
            raise ValueError(f"{name} must be non-negative")
